INSERT INTO _new VALUES ('Ⅰ.1','current','2022-03-02',NULL,'Ⅰ.1 일반사항 본 부속서의 기준은 이용자 및 유지관리인의 안전을 위해 중요하다. 다음의 요구조건은 소유자 또는 구매자의 준수사항으로 제조자와의 협의가 필요하다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.1','old','2013-09-15','2022-03-01','6.2.7 제조업체 표시 상‧하 승강장에서 잘 보이는 위치에 제조업체명(또는 로고)이 표기되어야 한다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.2.1','current','2022-03-02',NULL,'Ⅰ.2.1 뉴얼의 끝 지점 및 모든 지점의 자유공간을 포함한 에스컬레이터의 스텝 또는 무빙워크의 팔레트나 벨트 위의 틈새 높이는 2.3 m 이상이어야 한다.(그림 5의 h4 및 그림 I.1 참조)','[{"kind": "figure", "caption": "그림 Ⅰ.1 건축구조와 에스컬레이터/무빙워크 사이의 간격", "images": ["es_i1.png"], "table": null, "notes": "", "search": "그림 Ⅰ.1 건축구조와 에스컬레이터/무빙워크 사이의 간격 장애물(기둥 등) b9 ≥ 400 ㎜ Ⅰ.2.4 b10 ≥ 80 ㎜ Ⅰ.2.2 b11 ≥ 160 ㎜ Ⅰ.2.3 h4 ≥ 2,300 ㎜ Ⅰ.2.1 h12 ≥ 2,100 ㎜ Ⅰ.2.2"}]'::jsonb,'그림 Ⅰ.1 건축구조와 에스컬레이터/무빙워크 사이의 간격 장애물(기둥 등) b9 ≥ 400 ㎜ Ⅰ.2.4 b10 ≥ 80 ㎜ Ⅰ.2.2 b11 ≥ 160 ㎜ Ⅰ.2.3 h4 ≥ 2,300 ㎜ Ⅰ.2.1 h12 ≥ 2,100 ㎜ Ⅰ.2.2');
INSERT INTO _new VALUES ('Ⅰ.2.1','old','2013-09-15','2022-03-01','7.2.1 모든 지점에서 에스컬레이터의 스텝 또는 무빙워크의 팔레트나 벨트 위의 틈새 높이는 2.3 m 이상이어야 한다.(그림 2 및 그림 11의 h4 참조) 그 틈새 높이는 뉴얼의 끝까지 연장되어야 한다. 비고 2.3 m의 틈새 높이는 또한 제한이 없는 구역에 적용되어야 한다.','[{"kind": "figure", "caption": "그림 11 건축물과 에스컬레이터ㆍ무빙워크 사이의 치수", "images": ["es_i11.png"], "table": null, "notes": "", "search": "그림 11 건축물과 에스컬레이터ㆍ무빙워크 사이의 치수 장애물(기둥 등) b9 ≥ 400 mm 7.2.4 b10 ≥ 80 mm 7.2.2 b11 ≥ 160 mm 7.2.3 h4 ≥ 2.3 m 7.2.1 h12 ≥ 2.1 m 7.2.2"}]'::jsonb,'그림 11 건축물과 에스컬레이터ㆍ무빙워크 사이의 치수 장애물(기둥 등) b9 ≥ 400 mm 7.2.4 b10 ≥ 80 mm 7.2.2 b11 ≥ 160 mm 7.2.3 h4 ≥ 2.3 m 7.2.1 h12 ≥ 2.1 m 7.2.2');
INSERT INTO _new VALUES ('Ⅰ.2.2','current','2022-03-02',NULL,'Ⅰ.2.2 충돌을 방지하기 위해 에스컬레이터 또는 무빙워크 주위의 최소 자유구역은 그림 I.1과 같이 규정된다. 틈새 높이 h4는 손잡이 바깥에서 높이 h12로 감소될 수 있으며, 에스컬레이터의 스텝 또는 무빙워크의 팔레트나 벨트로부터 측정된 높이 h12는 2.1 m 이상이어야 한다. 손잡이 바깥 가장자리와 벽 또는 다른 장애물(그림 I.1의 b10 참조) 사이의 거리는 어떤 경우에도 80 ㎜ 이상이어야 하고 손잡이 하부 모서리 아래(그림 6의 b12 참조)에서 수직으로 25 ㎜ 이상이어야 한다. 다만, 적절한 조치에 의해 부상의 위험이 적어진 경우에는 이 공간이 작아지는 것이 허용된다.','[{"kind": "figure", "caption": "그림 Ⅰ.1 건축구조와 에스컬레이터/무빙워크 사이의 간격", "images": ["es_i1.png"], "table": null, "notes": "", "search": "그림 Ⅰ.1 건축구조와 에스컬레이터/무빙워크 사이의 간격 장애물(기둥 등) b9 ≥ 400 ㎜ Ⅰ.2.4 b10 ≥ 80 ㎜ Ⅰ.2.2 b11 ≥ 160 ㎜ Ⅰ.2.3 h4 ≥ 2,300 ㎜ Ⅰ.2.1 h12 ≥ 2,100 ㎜ Ⅰ.2.2"}]'::jsonb,'그림 Ⅰ.1 건축구조와 에스컬레이터/무빙워크 사이의 간격 장애물(기둥 등) b9 ≥ 400 ㎜ Ⅰ.2.4 b10 ≥ 80 ㎜ Ⅰ.2.2 b11 ≥ 160 ㎜ Ⅰ.2.3 h4 ≥ 2,300 ㎜ Ⅰ.2.1 h12 ≥ 2,100 ㎜ Ⅰ.2.2');
INSERT INTO _new VALUES ('Ⅰ.2.2','old','2013-09-15','2022-03-01','7.2.2 충돌을 방지하기 위해 에스컬레이터 또는 무빙워크 주위의 최소 자유구역은 그림 11과 같이 규정된다. 에스컬레이터의 스텝 또는 무빙워크의 팔레트나 벨트로부터 측정된 높이 h12는 2.1 m 이상 이어야한다. 핸드레일 외부 끝 부분과 벽 또는 다른 물체(그림 11의 b10 참조)사이의 거리는 핸드레일 하부 모서리 아래(그림 3의 b12 참조)에서 수평으로 80 mm 및 수직으로 25 mm 이상이어야 한다. 다만, 신축성이 있는 재료로 보호조치를 하고 주의표시를 하는 등 적절한 조치에 의해 부상의 위험이 적어진 경우에는 이 공간이 작아지는 것은 허용된다.','[{"kind": "figure", "caption": "그림 11 건축물과 에스컬레이터ㆍ무빙워크 사이의 치수", "images": ["es_i11.png"], "table": null, "notes": "", "search": "그림 11 건축물과 에스컬레이터ㆍ무빙워크 사이의 치수 장애물(기둥 등) b9 ≥ 400 mm 7.2.4 b10 ≥ 80 mm 7.2.2 b11 ≥ 160 mm 7.2.3 h4 ≥ 2.3 m 7.2.1 h12 ≥ 2.1 m 7.2.2"}]'::jsonb,'그림 11 건축물과 에스컬레이터ㆍ무빙워크 사이의 치수 장애물(기둥 등) b9 ≥ 400 mm 7.2.4 b10 ≥ 80 mm 7.2.2 b11 ≥ 160 mm 7.2.3 h4 ≥ 2.3 m 7.2.1 h12 ≥ 2.1 m 7.2.2');
INSERT INTO _new VALUES ('Ⅰ.2.2','old',NULL,'2013-09-14','4.3.2(10) 핸드레일 외측끝단에서 수평으로 0.5m 이내 및 디딤면에서 높이 2.1m 이내에 기둥이나 보 등이 있거나 건축물 천장부 또는 측면부 등에 요철부분이 있는 경우에는 승객이 다치지 않도록 신축성이 있는 재료(스폰지 등)로 보호조치를 하고 주의표시를 하여야 한다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.2.3','current','2022-03-02',NULL,'Ⅰ.2.3 평행하거나 십자형으로 교차된 서로 근접한 에스컬레이터 및 무빙워크의 경우, 손잡이 사이의 거리는 160 ㎜ 이상이어야 한다.(그림 Ⅰ.1의   참조)','[{"kind": "figure", "caption": "그림 Ⅰ.1 건축구조와 에스컬레이터/무빙워크 사이의 간격", "images": ["es_i1.png"], "table": null, "notes": "", "search": "그림 Ⅰ.1 건축구조와 에스컬레이터/무빙워크 사이의 간격 장애물(기둥 등) b9 ≥ 400 ㎜ Ⅰ.2.4 b10 ≥ 80 ㎜ Ⅰ.2.2 b11 ≥ 160 ㎜ Ⅰ.2.3 h4 ≥ 2,300 ㎜ Ⅰ.2.1 h12 ≥ 2,100 ㎜ Ⅰ.2.2"}]'::jsonb,'그림 Ⅰ.1 건축구조와 에스컬레이터/무빙워크 사이의 간격 장애물(기둥 등) b9 ≥ 400 ㎜ Ⅰ.2.4 b10 ≥ 80 ㎜ Ⅰ.2.2 b11 ≥ 160 ㎜ Ⅰ.2.3 h4 ≥ 2,300 ㎜ Ⅰ.2.1 h12 ≥ 2,100 ㎜ Ⅰ.2.2');
INSERT INTO _new VALUES ('Ⅰ.2.3','old','2013-09-15','2022-03-01','7.2.3 평행하거나 십자형으로 교차된 서로 근접한 에스컬레이터의 경우, 핸드레일 사이의 거리는 160 mm이상이어야 한다. (그림 11의 b11 참조)','[{"kind": "figure", "caption": "그림 11 건축물과 에스컬레이터ㆍ무빙워크 사이의 치수", "images": ["es_i11.png"], "table": null, "notes": "", "search": "그림 11 건축물과 에스컬레이터ㆍ무빙워크 사이의 치수 장애물(기둥 등) b9 ≥ 400 mm 7.2.4 b10 ≥ 80 mm 7.2.2 b11 ≥ 160 mm 7.2.3 h4 ≥ 2.3 m 7.2.1 h12 ≥ 2.1 m 7.2.2"}]'::jsonb,'그림 11 건축물과 에스컬레이터ㆍ무빙워크 사이의 치수 장애물(기둥 등) b9 ≥ 400 mm 7.2.4 b10 ≥ 80 mm 7.2.2 b11 ≥ 160 mm 7.2.3 h4 ≥ 2.3 m 7.2.1 h12 ≥ 2.1 m 7.2.2');
INSERT INTO _new VALUES ('Ⅰ.2.4','current','2022-03-02',NULL,'Ⅰ.2.4 건축물의 장애물로 인해 부상이 발생할 수 있는 장소는 적절한 예방조치가 취해져야 한다. 특히, 계단 교차점 및 십자형으로 교차하는 에스컬레이터 또는 무빙워크의 경우에는 그림 Ⅰ.2와 같이 틈새의 수직거리가 300 ㎜ 되는 곳까지 막는 등의 조치를 하되 부딪쳤을 때 신체에 상해를 주지 않는 탄력성이 있는 재료(스폰지 등)로 마감되어야 한다.(그림 5 및 그림 7의 h5 참조) 다만, 건축물 천장부 또는 측면부가 손잡이 외측 끝단에서 400 ㎜ 이상 떨어져 있는 경우에는 이 기준을 적용할 필요는 없다.(그림 Ⅰ.2 참조) 막는 조치의 끝부분에서 수평으로 250 ∼ 350 ㎜ 전방에 부드러운 재질의 비고정식 안전 보호판이 설치되어야 한다. 막는 조치 및 안전 보호판의 모서리나 끝부분은 날카롭지 않게 마감되어야 한다.','[{"kind": "figure", "caption": "그림 Ⅰ.2 막는 조치 및 안전 보호판", "images": ["es_i2.png"], "table": null, "notes": "", "search": "그림 Ⅰ.2 막는 조치 및 안전 보호판 건축물 천장부 25~35cm 30cm초과 막는 조치 핸드레일 안전보호판"}]'::jsonb,'그림 Ⅰ.2 막는 조치 및 안전 보호판 건축물 천장부 25~35cm 30cm초과 막는 조치 핸드레일 안전보호판');
INSERT INTO _new VALUES ('Ⅰ.2.4','old','2015-05-13','2022-03-01','7.2.4 건축물의 장애물로 인해 부상이 발생할 수 있는 장소는 적절한 예방조치가 취해져야 한다. 특히, 계단 교차점 및 십자형으로 교차하는 에스컬레이터 또는 무빙워크의 경우에는 그림 10과 같이 틈새의 수직거리가 300 mm 되는 곳까지 막는 등의 조치를 하되 부딪쳤을 때 신체에 상해를 주지 않는 탄력성이 있는 재료(스폰지 등)로 마감되어야 한다. (그림 2 및 그림 4의 h5 참조) 다만, 건축물 천장부 또는 측면부가 핸드레일 외측 끝단에서 400 mm 이상 떨어져 있는 경우 또는 교차각이 45°를 초과하는 경우에는 이 규정을 적용할 필요는 없다. (그림 11 참조) 막는 조치의 끝부분에서 수평으로 250 ∼ 350 mm 전방에 부드러운 재질의 비고정식 안전 보호판이 설치되어야 한다. 막는 조치 및 안전 보호판의 모서리나 끝부분은 날카롭지 않게 마감되어야 한다.','[{"kind": "figure", "caption": "그림 10 막는 조치 및 안전 보호판", "images": ["es_i10.png"], "table": null, "notes": "", "search": "그림 10 막는 조치 및 안전 보호판 건축물 천장부 25~35cm 30cm초과 막는 조치 핸드레일 안전보호판"}]'::jsonb,'그림 10 막는 조치 및 안전 보호판 건축물 천장부 25~35cm 30cm초과 막는 조치 핸드레일 안전보호판');
INSERT INTO _new VALUES ('Ⅰ.2.4','old','2013-09-15','2015-05-12','7.2.4 건축물의 장애물로 인해 부상이 발생할 수 있는 장소는 적절한 예방조치가 취해져야 한다. 특히, 계단 교차점 및 십자형으로 교차하는 에스컬레이터 또는 무빙워크의 경우에는 그림 10과 같이 틈새의 수직거리가 300 mm 되는 곳까지 막는 등의 조치를 하되 부딪쳤을 때 신체에 상해를 주지 않는 탄력성이 있는 재료(스폰지 등)로 마감되어야 한다. (그림 2 및 그림 4의 h5 참조) 다만, 건축물 천장부 또는 측면부가 핸드레일 외측 끝단에서 400 mm 이상 떨어져 있는 경우에는 이 규정을 적용할 필요는 없다. (그림 11 참조) 막는 조치의 끝부분에서 수평으로 250 ∼ 350 mm 전방에 부드러운 재질의 비고정식 안전 보호판이 설치되어야 한다. 막는 조치 및 안전 보호판의 모서리나 끝부분은 날카롭지 않게 마감되어야 한다.','[{"kind": "figure", "caption": "그림 10 막는 조치 및 안전 보호판", "images": ["es_i10.png"], "table": null, "notes": "", "search": "그림 10 막는 조치 및 안전 보호판 건축물 천장부 25~35cm 30cm초과 막는 조치 핸드레일 안전보호판"}]'::jsonb,'그림 10 막는 조치 및 안전 보호판 건축물 천장부 25~35cm 30cm초과 막는 조치 핸드레일 안전보호판');
INSERT INTO _new VALUES ('Ⅰ.2.4','old','2008-11-07','2013-09-14','4.3.2(14) 난간부와 교차하는 건축물 천장부 또는 측면부 등과의 사이에 운행방향(운행방향의 전환이 가능한 경우에는 양방향)으로 생기는 3각부에 사람의 머리 등 신체의 일부가 끼이는 것을 방지하기 위하여 다음 각항의 조치가 되어 있어야 한다. ① <그림 4>과 같이 3각부가 형성되지 않도록 3각부 틈새의 수직거리가 30㎝ 되는 곳까지 막는 등의 조치를 하되 디딤판의 진행속도로 부딪쳤을 때 신체에 상해를 주지 않는 탄력성이 있는 재료(스폰지 등)로 마감처리 하여야 한다. 다만, 건축물 천장부 또는 측면부가 핸드레일외측 끝단에서 50㎝ 이상 떨어져 있는 경우 또는 교차각이 45°를 초과하는 경우에는 그러하지 아니하다. ② 사람이 3각부에 충돌하는 것을 경고하기 위하여 25～35㎝ 전방에 신체상해의 우려가 없는 재질의 비고정식 안전 보호판 등이 설치되어 있어야 한다. 다만, 건축물 천장부 또는 측면부가 핸드레일 외측 끝단에서 50㎝ 이상 떨어져 있는 경우 또는 교차각이 60°를 초과하는 경우에는 그러하지 아니하다. ③ 3각부의 막는 재료 및 안전보호판과 건축물의 천장부 등 사람이 부딪칠 수 있는 부분의 모서리나 끝부분은 날카롭지 않도록 마감처리 되어 있어야 한다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.2.4','old','2001-06-18','2008-11-06','4.3.2(14) 난간부와 교차하는 건축물 천장부 또는 측면부 등과의 사이에 생기는 3각부에 사람의 머리 등 신체의 일부가 끼이는 것을 방지하기 위하여 다음 각항의 조치가 되어 있어야 한다. ① 그림 1과 같이 3각부가 형성되지 않도록 3각부 틈새의 수직거리가 30㎝ 되는 곳까지 막는 등의 조치를 하되 디딤판의 진행속도로 부딪쳤을 때 신체에 상해를 주지 않는 탄력성이 있는 재료(스폰지 등)로 마감처리 하여야 한다. 다만, 건축물 천장부 또는 측면부가 핸드레일외측 끝단에서 50㎝ 이상 떨어져 있는 경우 또는 교차각이 45°를 초과하는 경우에는 그러하지 아니하다. ② 사람이 3각부에 충돌하는 것을 경고하기 위하여 25～35㎝ 전방에 신체상해의 우려가 없는 재질의 비고정식 안전보호판 등이 설치되어 있어야 한다. 다만, 건축물 천장부 또는 측면부가 핸드레일 외측 끝단에서 50㎝ 이상 떨어져 있는 경우 또는 교차각이 60°를 초과하는 경우에는 그러하지 아니하다. ③ 3각부의 막는 재료 및 안전보호판과 건축물의 천장부 등 사람이 부딪칠 수 있는 부분의 모서리나 끝부분은 날카롭지 않도록 마감처리 되어 있어야 한다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.2.4','old','1999-01-14','2001-06-17','4.3.2(14) 난간부와 교차하는 건축물 천장부 또는 측면부 등과의 사이에 생기는 3각부에 사람의 머리 등 신체의 일부가 끼이는 것을 방지하기 위하여 다음 각항의 조치가 되어 있어야 한다. ① 그림 1과 같이 3각부가 형성되지 않도록 3각부 틈새의 수직거리가 30㎝ 되는 곳까지 막는 등의 조치를 하되 디딤판의 진행속도로 부딪쳤을 때 신체에 상해를 주지 않는 탄력성이 있는 재료(스폰지 등)로 마감처리 하여야 한다. 다만, 건축물 천장부 또는 측면부가 핸드레일외측 끝단에서 50㎝ 이상 떨어져 있는 경우 또는 교차각이 45°를 초과하는 경우에는 그러하지 아니하다. ② 사람이 3각부에 충돌하는 것을 경고하기 위하여 25～35㎝ 전방에 신체상해의 우려가 없는 재질의 비고정식 안전보호판 등이 설치되어 있어야 한다. 다만, 건축물 천장부 또는 측면부가 핸드레일 외측 끝단에서 50㎝ 이상 떨어져 있는 경우 또는 교차각이 60°를 초과하는 경우에는 그러하지 아니하다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.2.4','old',NULL,'1999-01-13','4.3.2(14) 난간부와 교차하는 건축물 천장부 또는 측면부 등과의 사이에 생기는 3각부에 사람의 머리 등 신체의 일부가 끼이는 것을 방지하기 위하여 다음 각항의 조치가 되어 있어야 한다. ① 그림 1과 같이 3각부가 형성되지 않도록 3각부 틈새의 수직거리가 30㎝ 되는 곳까지 막는 등의 조치를 하되 디딤판의 진행속도로 부딪쳤을 때 신체에 상해를 주지 않는 탄력성이 있는 재료(스폰지 등)로 마감처리 하여야 한다. 다만, 건축물 천장부 또는 측면부가 핸드레일외측 끝단에서 50㎝ 이상 떨어져 있는 경우 또는 교차각이 45°를 초과하는 경우에는 그러하지 아니하다. ② 사람이 막은 부위에 충돌하는 것을 경고하기 위하여 25～35㎝ 전방에 신체상해의 우려가 없는 재질(아크릴판 등)의 비고정식 안전보호판 등이 설치되어 있어야 한다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.2.5','current','2022-03-02',NULL,'Ⅰ.2.5 각각의 에스컬레이터 또는 무빙워크의 출구에는 승객을 수용할 수 있는 충분한 자유공간이 있어야 한다. 자유공간의 폭은 각각의 손잡이 바깥 끝단에서 80 ㎜를 더한 지점 사이의 거리 이상이어야 한다. 자유공간의 깊이는 난간의 끝에서부터 측정하여 2.5 m 이상이어야 한다. 자유공간의 폭이 손잡이 바깥 끝단에서 80 ㎜를 더한 지점 사이의 거리에 2배 이상으로 증가되는 경우 2 m로 감소하는 것이 허용된다. 이러한 자유공간은 건물 내 다른 승객들의 흐름 등에 영향을 받지 않는다고 가정할 때, 모든 조건에서 적용될 수 있는 최소 허용 치수이다. 비고 안내 울타리 및 운행 안내 표시 기둥은 Ⅰ.5 참조 자유공간의 중첩은 허용되지 않고 측면 이동은 허용된다. 자유공간의 바닥은 평평해야 한다. 경사도는 6 °이하이어야 한다. 자유공간 내의 고정형 계단은 허용되지 않는다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.2.5','old','2013-09-15','2022-03-01','7.2.5 각각의 에스컬레이터나 무빙워크의 출구에서 사람을 수용할 수 있는 충분한 자유공간이 있어야 한다. 자유공간의 폭은 각 면에 80 mm를 더한 핸드레일의 외부 끝단 사이의 거리에 상응하는 값 이상이어야 한다. 그 깊이는 난간의 끝에서부터 측정하여 2.5 m 이상이어야 한다. 자유공간의 폭이 각 면에 80 mm를 더한 핸드레일의 외부 끝단 사이의 거리 2배 이상 증가된 경우에는 2 m로 감소하는 것이 허용된다. 비고 연속되는 에스컬레이터 및 무빙워크에 대한 자유공간의 깊이는 이용의 유형(승객용 또는 수송 장치를 포함한 승객용, 중간 출입구의 개수, 관련된 방침과 이론적 수용능력 등)에 따라 각각의 여건에 맞게 결정되어야 한다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.2.5','old','2001-06-18','2013-09-14','3.3.1(7) 승강장의 면적은 다음 기준에 적합하여야 한다. ① 승강장의 폭은 핸드레일 중심선간의 거리 이상이어야 한다. ② 승강장의 길이는 난간 끝단에서 진행방향으로 2.5m 이상이어야 한다. 다만, 승강장의 폭이 핸드레일 중심선간 거리의 2배 이상일 경우에는 2.0m 이상으로 할 수 있다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.2.5.1','current','2022-03-02',NULL,'Ⅰ.2.5.1 에스컬레이터/무빙워크 승강장에 대면하는 방화셔터가 손잡이 반환부의 선단에서 2 m 이내에 설치된 경우 방화셔터가 닫히기 시작할 때 연동하여 자동으로 정지시키는 장치가 설치되어야 한다. 여러 개의 방화셔터가 하나의 구획으로 구성되어 그것들이 동시에 폐쇄되는 경우 어느 쪽의 셔터와 연동되어도 된다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.2.5.1','old','2013-09-15','2022-03-01','7.4.1 에스컬레이터에는 승강장에 근접하여 설치된 방화셔터가 닫히기 시작할 때 자동으로 에스컬레이터를 정지시키는 장치가 설치되어야 한다. 7.4.2 에스컬레이터 승강장에 대면하는 방화셔터가 핸드레일 반환부의 선단에서 2 m 이내에 있는 것에서는 당해 에스컬레이터는 그 셔터의 폐쇄개시와 연동하여 정지하여야 한다. 또한, 상기의 셔터를 포함하여 여러 개의 방화셔터가 하나의 구획으로 구성되어 그것들이 동시에 폐쇄되는 경우에 에스컬레이터의 연동정지는 어느 쪽의 셔터와 연동되어도 된다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.2.5.1','old',NULL,'2013-09-14','3.3.2(2) 승강장에 근접하여 설치한 방화셔터 등이 닫히기 시작할 때 디딤판의 승강을 자동적으로 정지시키는 장치 4.3.2(2) 에스컬레이터 승강장에 대면하는 방화셔터가 핸드레일 반환부의 선단에서 2m 이내에 있는 것에서는 당해 에스컬레이터는 그 셔터의 폐쇄개시와 연동하여 정지하여야 한다. 또한, 상기의 셔터를 포함하여 여러개의 방화셔터가 하나의 구획으로 구성되어 그것들이 동시에 폐쇄되는 경우에 에스컬레이터의 연동정지는 어느 쪽의 셔터와 연동되어도 된다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.2.5.2','current','2019-03-28',NULL,'Ⅰ.2.5.2 연속으로 이어지는 에스컬레이터/무빙워크 사이의 공간이 충분하지 않은 경우, 다음과 같은 추가적인 비상정지장치가 제공되어야 한다. 가) 에스컬레이터/무빙워크 내부에서 닿을 수 있고, 나) 디딤판이 콤 교차선에 도달하기 전, 2 m ~ 3 m 사이의 거리에 있고, 다) 손잡이 상부면에서 액추에이터(예: 누름 버튼, 핸들) 중심까지 측정된 수직범위가 손잡이 아래로 200 ㎜ 위로 400 ㎜ 이내에 있을 것 난간의 내외부에 있는 조립품은 걸림(또는 끼임)으로 인한 손상의 위험을 제거하는 방식으로 배열되고 형성될 때 허용된다.(5.5.2.4, Ⅰ.2.2 및 Ⅰ.5를 고려함)',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.2.6','current','2022-03-02',NULL,'Ⅰ.2.6 중간 출입구 없이 연속되는 에스컬레이터 및 무빙워크의 경우, 동일한 승객 수송능력을 가져야 한다. 5.12.2.7.8에 따른 안전장치가 제공되어야 한다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.2.6','old','2013-09-15','2022-03-01','7.2.6 중간 출입구 없이 연속되는 에스컬레이터 및 무빙워크의 경우에는 모두 동일한 수용능력을 가져야 한다.[표 5의 아) 참조]',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.2.7','current','2022-03-02',NULL,'Ⅰ.2.7 사람이 승강장에서 손잡이 바깥 끝단에 접촉할 수 있고, 추락하는 등의 위험한 상황에 처할 수 있는 곳에서는 적절한 예방 조치가 이루어져야 한다.(그림 I.3 참조) 몇가지 예는 다음과 같다. - 영구적인 보호수단의 설치로 해당공간으로의 진입 방지 - 위험 지역에서 고정난간의 건축구조 높이를 손잡이 위로 100 ㎜이상 높게 하고, 손잡이 바깥 끝단에서부터 80 ㎜에서 120 ㎜ 사이에 위치토록 함','[{"kind": "figure", "caption": "그림 Ⅰ.3 승강장 울타리의 예시 (단위: ㎜)", "images": ["es_i3.png"], "table": null, "notes": "", "search": "그림 Ⅰ.3 승강장 울타리의 예시 단위 ㎜ 이 그림은 일정한 비율로 그려져 있지 않고 단지 기준만을 설명한다"}]'::jsonb,'그림 Ⅰ.3 승강장 울타리의 예시 단위 ㎜ 이 그림은 일정한 비율로 그려져 있지 않고 단지 기준만을 설명한다');
INSERT INTO _new VALUES ('Ⅰ.2.7','old','2015-05-13','2022-03-01','7.2.7 사람이 승강장에서 핸드레일 외부 끝단에 접촉할 가능성이 있고, 사람이 추락하는 등의 위험한 상황에 처할 수 있는 곳에서는 적절한 조치가 이루어져야 한다.(그림 12 참조) 비고 상기와 같은 적절한 조치로 다음과 같이 할 수 있다. - 영구적인 보호수단의 설치로 공간으로의 출입 방지 - 위험 지역에서 핸드레일 위로 100 mm이상, 그리고, 핸드레일 외부 끝단에서부터 80 mm에서 120 mm 사이에 위치한 고정난간의 높이 증가','[{"kind": "figure", "caption": "그림 12 승강장의 보호수단", "images": ["es_i12.png"], "table": null, "notes": "", "search": "그림 12 승강장의 보호수단 울타리 100 120 80"}]'::jsonb,'그림 12 승강장의 보호수단 울타리 100 120 80');
INSERT INTO _new VALUES ('Ⅰ.2.7','old','2013-09-15','2015-05-12','7.2.7 사람이 승강장에서 핸드레일 외부 끝단에 접촉할 가능성이 있고, 난간을 넘는 것과 같은 위험한 상황에 처할 수 있는 곳에서는 적절한 조치가 이루어져야 한다.(그림 12 참조) 예를 들면, 다음과 같이 할 수 있다. - 영구적인 장애물의 설치로 공간으로의 출입 방지 - 위험 지역에서 핸드레일 위로 100 mm이상, 그리고, 핸드레일 외부 끝단에서부터 80 mm에서 120 mm 사이에 위치한 고정난간의 높이 증가','[{"kind": "figure", "caption": "그림 12 승강장의 보호수단", "images": ["es_i12.png"], "table": null, "notes": "", "search": "그림 12 승강장의 보호수단 울타리 100 120 80"}]'::jsonb,'그림 12 승강장의 보호수단 울타리 100 120 80');
INSERT INTO _new VALUES ('Ⅰ.2.8','current','2022-03-02',NULL,'Ⅰ.2.8 에스컬레이터 또는 무빙워크의 주변, 특히 콤 부근은 밝게 비춰져야 한다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.2.8','old','2013-09-15','2022-03-01','7.2.8 콤을 포함한 승강장에서의 조도는 바닥에서 측정하여 콤의 교차선에서 50 Lux 이상이어야 한다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.2.9','current','2022-03-02',NULL,'Ⅰ.2.9 주변 공간 및/또는 기기 자체에 조명을 배치하는 것은 허용된다. 콤을 포함한 승강장 조도는 해당 구역의 일반 조명 조도와 관련되며, 바닥에서 측정된 콤 교차선에서의 조도는 50 ㏓ 이상이어야 한다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.2.9','old','2013-09-15','2022-03-01','7.2.8 콤을 포함한 승강장에서의 조도는 바닥에서 측정하여 콤의 교차선에서 50 Lux 이상이어야 한다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.3.1','current','2022-03-02',NULL,'Ⅰ.3.1 기계류 공간에 사람의 안전한 접근이 제공되어야 한다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.3.1','old','2013-09-15','2022-03-01','7.3.1 구동기 공간으로의 안전한 출입이 제공되어야 한다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.3.2','current','2022-03-02',NULL,'Ⅰ.3.2 기계류 공간은 잠글 수 있어야하고 자격자만이 접근할 수 있어야 한다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.3.2','old','2013-09-15','2022-03-01','7.3.2 구동기 공간에는 잠금장치가 있어야 하고 오직 권한 있는 사람만이 출입할 수 있어야 한다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.3.3','current','2022-03-02',NULL,'Ⅰ.3.3 기계류 공간에는 영구적으로 설치된 전기조명장치가 다음과 같이 제공되어야 한다. 가) 작업구역의 바닥에서 200 ㏓ 이상 나) 작업구역으로 접근하는 통로의 바닥에서 50 ㏓ 이상',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.3.3','old','2013-09-15','2022-03-01','7.3.3 구동기 공간은 다음과 같은 조명이 영구적으로 설치되어야 한다. 가) 작업공간의 바닥에서 200 lx 이상 나) 작업공간으로 접근하는 통로의 바닥에서 50 lx 이상',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.3.4','current','2022-03-02',NULL,'Ⅰ.3.4 비상조명은 모든 기계류 공간에서 작업하는 모든 인원의 안전한 대피를 위해 설치되어야 한다. 비고 비상조명은 점검 등 유지관리 업무를 지속하기 위한 것은 아니다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.3.4','old','2013-09-15','2022-03-01','7.3.4 비상조명은 구동기 공간의 어떤 공간에서 일하는 작업자의 안전한 피난을 위해 설치되어야 한다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.3.5','current','2022-03-02',NULL,'Ⅰ.3.5 기계류 공간의 크기는 설비, 특히 전기설비의 작업이 쉽고 안전하도록 충분해야 한다. 작업구역에서 유효 높이는 2 m 이상이어야 하고, 다음 사항에 적합해야 한다. 가) 제어패널 및 캐비닛 전면의 유효 수평면적은 아래와 같아야 한다. 1) 깊이는 외함의 표면에서 측정하여 0.7 m 이상 2) 폭은 0.5 m 또는 제어패널과 캐비닛의 전체 폭 중에서 큰 값 이상 나) 움직이는 부품의 점검 등 유지관리 업무가 필요한 지점에서 유효 수평면적은 0.5 m × 0.6 m 이상이어야 한다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.3.5','old','2013-09-15','2022-03-01','7.3.5 구동기 공간의 크기는 설비, 특히 전기설비의 작업이 쉽고 안전하도록 충분하여야 한다. 작업구역에서 유효 높이는 2 m 이상이어야 하고 다음 사항에 적합하여야 한다. 가) 제어 패널 및 캐비닛 전면의 유효 수평면적은 아래와 같아야 한다. 1) 폭은 0.5 m 또는 제어 패널‧캐비닛의 전체 폭 중에서 큰 값 이상 2) 깊이는 외함의 표면에서 측정하여 0.7 m 이상 나) 움직이는 부품의 유지보수 및 점검을 위한 유효 수평면적은 0.5 m × 0.6 m 이상이어야 한다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.3.6','current','2022-03-02',NULL,'Ⅰ.3.6 이동을 위한 유효 높이는 1.8 m 이상이어야 한다. 이동을 위한 통로의 폭은 0.5 m 이상이어야 한다. 다만, 움직이는 부품이 없는 경우에는 0.4 m로 줄일 수 있다. 이동을 위한 공간의 유효 높이는 다음과 같은 바닥에서부터 구조물의 지붕 및 빔 하부까지 측정하여 1.8 m 이상이어야 한다. 가) 접근지역 나) 작업구역',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.3.6','old','2013-09-15','2022-03-01','7.3.6 이동을 위한 통로의 폭은 0.5 m 이상이어야 한다. 다만, 움직이는 부품이 없는 경우에는 0.4 m로 줄일 수 있다. 이동을 위한 공간의 유효 높이는 다음과 같은 바닥에서부터 구조물의 지붕ㆍ빔 하부까지 측정하여 1.8 m 이상이어야 한다. 가) 접근지역 나) 작업구역',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.3.7','current','2019-03-28',NULL,'Ⅰ.3.7 기계류 공간의 유효 높이는 2.0 m 이상이어야 한다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.4.1','current','2019-03-28',NULL,'Ⅰ.4.1 일반사항 쇼핑 카트 및 수하물 카트를 에스컬레이터 또는 무빙워크로 가져올 수 있는 합리적이고 예측 가능한 위험이 있는 경우, 다음과 같은 조건이 주어지면 위험을 제거하고 접근을 방지하기 위한 적절한 조치가 취해져야 한다. 가) 에스컬레이터의 경우 - 주변 지역에서 쇼핑 카트 또는 수하물 카트를 사용할 수 있는 경우 - 쇼핑 카트 또는 수하물 카트가 에스컬레이터에 가까이 있지 않지만 에스컬레이터로 가져올 수 있는 것이 합리적이고 예측 가능한 경우 나) 무빙워크 - 쇼핑 카트 또는 수하물 카트가 무빙워크에서 사용되지 않도록 한 경우 비고 카트가 난간과 진입방지대 사이를 통과하지 못하도록 카트의 폭을 정의하는 것은 소유자의 책임이다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.4.2','current','2019-03-28',NULL,'Ⅰ.4.2 진입방지대 진입방지대가 사용되는 경우, 다음 요구조건이 충족되어야 한다. 가) 진입방지대는 입구에만 설치해야 한다. 자유구역에서는 출구에 설치할 수 없다. 나) 진입방지대 설계는 다른 위험을 초래하지 않아야 한다. 다) 뉴얼의 끝과 진입방지대 및 진입방지대와 진입방지대 사이의 자유로운 입구 폭은 500 ㎜ 이상이어야 하며, 사용되는 쇼핑 카트 또는 수하물 카트 유형의 폭보다 작아야 한다. 라) 진입방지대의 높이는 900 ㎜에서 1,100 ㎜ 사이이어야 한다. 마) 진입방지대 및 고정장치는 높이 200 ㎜에서 3,000 N의 수평력을 견뎌야 한다. 비고 이 힘은 쇼핑카트의 경우 EN 1929-1 [5]에 따른 섀시의 충격으로 발생/수하물 카트의 경우 160 ㎏ 하중을 적재하여 1㎧ 의 속도로 움짐임으로 발생 바) 진입방지대는 가급적이면 건물 구조물에 고정되어야 한다. 승강장 플레이트에 고정시키는 것도 허용된다. 이 경우, 마)에서 정의된 힘이 적용될 때, 영구 변형 및 틈새의 증가/추가가 없어야 한다.',NULL,NULL);
INSERT INTO _new VALUES ('Ⅰ.5','current','2019-03-28',NULL,'Ⅰ.5 고정 안내 울타리 및 운행 안내 표시 기둥(traffic columns) 자유공간에서 고정 안내 울타리 및/또는 운행 안내 표시 기둥(예: 제어 장치 및 비상 정지장치등 포함)이 필요한 경우, 이들의 설계가 다른 위험을 유발해서는 안되며, 다음 요구 조건이 충족되어야 한다. 가) 안내 울타리 또는 운행 안내 표시 기둥은 손잡이의 임의 지점까지 최소 수평거리(반경)가 500 ㎜ 이상이 되어야하며, 손잡이의 중심선 바깥쪽에 위치해야한다.(그림 Ⅰ.4의 배치 A 참조) 나) 안내 울타리 또는 운행 안내 표시 기둥이 손잡이의 중심선 바깥에 위치하고 추가 울타리가 안내 울타리 또는 운행 안내 표시 기둥과 난간 뉴얼의 수직 중심선 사이에 설치되어 있으면 손잡이의 임의 지점까지의 최소 수평거리(반경)를 300 ㎜로 줄일 수 있다.(그림 Ⅰ.4의 배치 B 참조) 추가 울타리는 손잡이 바깥 끝단과 80 ㎜에서 120 ㎜ 사이의 측면 거리를 가져야 하고, 최소한 뉴얼로 들어가는 손잡이의 실제 가장 낮은 지점과 난간 데크 사이의 구역을 막아야 하며, 추가 울타리의 틈새는 25 ㎜ 미만이 되어야 한다.(그림 Ⅰ.3 참조) 다) 안내 울타리 또는 운행 안내 표시 기둥이 손잡이 바깥 끝단의 외부에 위치하고 추가 울타리가 안내 장벽 또는 운행 안내 표시 기둥과 난간 뉴얼의 수직 중심선 사이에 설치되어 있으면 손잡이의 임의 지점까지의 최소 수평거리(반경)는 180 ㎜로 줄일 수 있다.(그림 Ⅰ.4의 배치C 참조) 추가 울타리는 손잡이 바깥 끝단과 80 ㎜에서 120 ㎜ 사이의 측면 거리를 가져야 하고, 최소한 뉴얼로 들어가는 손잡이의 실제 가장 낮은 지점과 난간 데크 사이의 구역을 막아야 하며, 추가 울타리의 틈새는 25 ㎜ 미만이 되어야 한다.(그림 Ⅰ.3 참조) 라) 안내 울타리 또는 운행 안내 표시 기둥이 둥근 형태로 되어 있고 손잡이 바깥 끝단의 외부에 위치하고 추가 울타리가 안내 울타리 또는 운행 안내 표시 기둥과 난간 뉴얼의 수직 중심선 사이에 설치되어 있으면 손잡이의 임의 지점까지의 최소 수평거리(반경)는 100 ㎜로 줄일 수 있다. (그림 Ⅰ.4의 배치D 참조) 추가 울타리는 손잡이 바깥 끝단과 80 ㎜에서 120 ㎜ 사이의 측면 거리를 가져야 하고, 최소한 뉴얼로 들어가는 손잡이의 실제 가장 낮은 지점과 난간데크 사이의 구역을 막아야 하며, 추가 울타리의 틈새는 25 ㎜ 미만이 되어야 한다.(그림 Ⅰ.4 참조) 추가로, 다음과 같은 특별 요구조건이 적용되어야 한다. 마) 안내 울타리와 운행 안내 표시 기둥 및 그 고정 장치는 장치의 상단에 가해지는 1 kN/m의 수평력을 견뎌야한다. 바) 안내 울타리와 운행 안내 표시 기둥은 가급적이면 건물 구조물에 고정되어야 한다. 승강장 플레이트에 고정시키는 것도 허용된다. 이 경우, 마)에서 정의된 힘이 적용될 때, 영구 변형 및 틈새의 증가/추가가 없어야 한다. 사) 운행 안내 표시 기둥의 높이는 손잡이의 높이 이상이어야 한다. 아) 안내 울타리의 높이는 난간데크의 높이 이상이어야 한다. 자) 안내 울타리와 운행 안내 표시 기둥이 자유공간 안에 배치되면 자유공간의 크기는 동일하게 유지되어야 하며, 이 경우 길이가 연장되어야 한다. 차) 안내 울타리와 운행 안내 표시 기둥은 출구를 막는 구조적 수단으로 간주하지 않는다. 자유공간과 근접한 곳에 있는 안내 울타리와 운행 안내 표시 기둥 또한 상기의 요구조건이 적용된다. 자유공간 밖의 근접한 곳에 있는 기타 장치 및 설비에는 가), 나), 다), 라)의 조건이 적용된다.','[{"kind": "figure", "caption": "그림 Ⅰ.4 자유공간 내에 고정된 안내 울타리 및 운행 안내 표시 기둥의 가능 위치 (단위: ㎜)", "images": ["es_i4.png"], "table": null, "notes": "", "search": "그림 Ⅰ.4 자유공간 내에 고정된 안내 울타리 및 운행 안내 표시 기둥의 가능 위치 A 위치 B 위치 C 위치 D 위치 원형 기둥 추가 울타리 R 500 R 300 R 180 R 100 손잡이 중심선 외부 손잡이 바깥 끝단 외부"}, {"kind": "figure", "caption": "그림 Ⅰ.3 승강장 울타리의 예시 (단위: ㎜)", "images": ["es_i3.png"], "table": null, "notes": "", "search": "그림 Ⅰ.3 승강장 울타리의 예시 단위 ㎜ 이 그림은 일정한 비율로 그려져 있지 않고 단지 기준만을 설명한다"}]'::jsonb,'그림 Ⅰ.4 자유공간 내에 고정된 안내 울타리 및 운행 안내 표시 기둥의 가능 위치 A 위치 B 위치 C 위치 D 위치 원형 기둥 추가 울타리 R 500 R 300 R 180 R 100 손잡이 중심선 외부 손잡이 바깥 끝단 외부
INSERT INTO _new VALUES ('Ⅰ.6','current','2019-03-28',NULL,'Ⅰ.6 전력 공급 전기 공급 및 전기 보호 기준(예: 감전, 단락, 과부하)에 대해 소유자(또는 구매자)와 제조자 간에 합의가 이루어져야 한다. 설치는 KS C IEC 60204-1에 따라야 한다.',NULL,NULL);
