-- 에스컬레이터 연혁: 부속서 Ⅰ(건축물과의 공유영역) 신규 49행 + 그림 첨부
-- 가이드가 인용하는 부속서 Ⅰ 조문(Ⅰ.2.1~Ⅰ.5 등)의 연혁이 DB에 없어 신규로 넣습니다. 기존 행은 건드리지 않습니다.
-- 신규 행이 정확히 49건 들어갔을 때만 저장하고, 아니면 전체 롤백합니다(이미 반영된 경우도 롤백).
-- 코드 배포 전에 먼저 실행해야 합니다.
\set ON_ERROR_STOP on
BEGIN;
ALTER TABLE public.inspection_item_revisions ADD COLUMN IF NOT EXISTS attachments jsonb;
ALTER TABLE public.inspection_item_revisions ADD COLUMN IF NOT EXISTS attachments_text text;
CREATE TEMP TABLE _new (item_id text, typ text, eff text, exp text, descr text, att jsonb, atxt text) ON COMMIT DROP;
그림 Ⅰ.3 승강장 울타리의 예시 단위 ㎜ 이 그림은 일정한 비율로 그려져 있지 않고 단지 기준만을 설명한다');
WITH n AS (INSERT INTO public.inspection_item_revisions (item_id,equipment_type,effective_date,expiry_date,introduction_type,description,attachments,attachments_text)
  SELECT item_id,'에스컬레이터',eff,exp,typ,descr,att,atxt FROM _new x WHERE NOT EXISTS (SELECT 1 FROM public.inspection_item_revisions r WHERE r.equipment_type='에스컬레이터' AND r.item_id=x.item_id AND r.introduction_type=x.typ AND r.effective_date IS NOT DISTINCT FROM x.eff AND r.expiry_date IS NOT DISTINCT FROM x.exp) RETURNING 1) SELECT count(*) AS inserted FROM n \gset
SELECT :inserted AS inserted_rows;
\if `[ :inserted -eq 49 ] && echo 1 || echo 0`
  COMMIT;
  \echo '완료'
\else
  ROLLBACK;
  \echo '건수가 맞지 않아 취소했습니다(이미 반영되었거나 같은 조문이 있음)'
\endif
